private val parsedSmartMusicCopies = HashMap<String, SmartMusicCopy>()

internal fun smartMusicCopy(code: String): SmartMusicCopy = synchronized(parsedSmartMusicCopies) {
    parsedSmartMusicCopies.getOrPut(code) {
        SmartMusicCopy(localizedValueOrEnglish(smartMusicBundles, code).split('|'))
    }
}

internal fun smartMusicLocalizationCodes(): Set<String> = smartMusicBundles.keys

internal fun smartMusicRawEntries(code: String): List<String> = smartMusicBundles.getValue(code).split('|')
